const NT_SETUP_SQL="-- Finlume Notes: one-time setup (run once in Supabase -> SQL Editor)\n-- Creates the notes table, row-level security, realtime sync and a private\n-- storage bucket for note attachments. Safe to run more than once.\n\ncreate table if not exists public.finlume_notes (\n  id          text primary key,\n  user_id     uuid not null references auth.users(id) on delete cascade,\n  title       text not null default '',\n  body        text not null default '',\n  body_text   text not null default '',\n  tags        jsonb not null default '[]'::jsonb,\n  pinned      boolean not null default false,\n  pin_order   integer not null default 0,\n  archived    boolean not null default false,\n  reminder    jsonb,\n  attachments jsonb not null default '[]'::jsonb,\n  created_at  timestamptz not null default now(),\n  edited_at   timestamptz not null default now(),\n  updated_at  timestamptz not null default now(),\n  deleted_at  timestamptz\n);\n\ncreate index if not exists finlume_notes_user_updated_idx\n  on public.finlume_notes (user_id, updated_at desc);\n\nalter table public.finlume_notes enable row level security;\n\ndrop policy if exists \"notes select own\" on public.finlume_notes;\ndrop policy if exists \"notes insert own\" on public.finlume_notes;\ndrop policy if exists \"notes update own\" on public.finlume_notes;\ndrop policy if exists \"notes delete own\" on public.finlume_notes;\n\ncreate policy \"notes select own\" on public.finlume_notes for select using (auth.uid() = user_id);\ncreate policy \"notes insert own\" on public.finlume_notes for insert with check (auth.uid() = user_id);\ncreate policy \"notes update own\" on public.finlume_notes for update using (auth.uid() = user_id) with check (auth.uid() = user_id);\ncreate policy \"notes delete own\" on public.finlume_notes for delete using (auth.uid() = user_id);\n\n-- Realtime (so a change on one device shows up on the others)\nalter table public.finlume_notes replica identity full;\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_publication_tables\n    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'finlume_notes'\n  ) then\n    alter publication supabase_realtime add table public.finlume_notes;\n  end if;\nend $$;\n\n-- Private bucket for attachments (10 MB per file). Files live under <user id>/<note id>/...\ninsert into storage.buckets (id, name, public, file_size_limit)\nvalues ('note-files', 'note-files', false, 10485760)\non conflict (id) do update set public = false, file_size_limit = 10485760;\n\ndrop policy if exists \"note files select own\" on storage.objects;\ndrop policy if exists \"note files insert own\" on storage.objects;\ndrop policy if exists \"note files update own\" on storage.objects;\ndrop policy if exists \"note files delete own\" on storage.objects;\n\ncreate policy \"note files select own\" on storage.objects for select\n  using (bucket_id = 'note-files' and (storage.foldername(name))[1] = auth.uid()::text);\ncreate policy \"note files insert own\" on storage.objects for insert\n  with check (bucket_id = 'note-files' and (storage.foldername(name))[1] = auth.uid()::text);\ncreate policy \"note files update own\" on storage.objects for update\n  using (bucket_id = 'note-files' and (storage.foldername(name))[1] = auth.uid()::text);\ncreate policy \"note files delete own\" on storage.objects for delete\n  using (bucket_id = 'note-files' and (storage.foldername(name))[1] = auth.uid()::text);\n";
